# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ASRISAADET GENÇLERİNİN PEYGAMBERİMİZE (SAV) SEVGİSİ (PH.6.2.2)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Zeyd bin Hârise (ra)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Babası ve amcası fidye verip</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">onu götürmeye geldiğinde</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Peygamberimizin şefkatini</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11.5" fill="#1e3a8a">ve sevgisini tercih ederek</text>\n  <text x="125" y="178" text-anchor="middle" font-size="11.5" fill="#1e3a8a">O\'nun yanında kalmıştır.</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Vefa ve Gönülden Bağlılık</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Enes bin Mâlik (ra)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• On yaşından itibaren 10 yıl</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">boyunca Peygamberimizin</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11.5" fill="#14532d">yanında bulunmuş; O\'ndan</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11.5" fill="#14532d">bir kez bile incitici söz veya</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11.5" fill="#14532d">azarlama duymamıştır.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Şefkat ve Nezaket İklimi</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Sünnete İttiba (Uyma)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#713f12">• Genç sahabiler sevgilerini</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#713f12">Peygamberimizin ahlakını</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11.5" fill="#713f12">ve sünnetini hayatlarına</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11.5" fill="#713f12">aktararak, O\'nun öğütlerini</text>\n  <text x="575" y="178" text-anchor="middle" font-size="11.5" fill="#713f12">titizlikle uygulayarak gösterdi.</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Sevginin Göstergesi: Örnek Alma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENÇ SAHABİLERİN İLİM ÖĞRENME GAYRETİ VE SUFFE OKULU</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Ashâb-ı Suffe (Mescid-i Nebevî Okulu)</text>\n  <text x="38" y="98" font-size="11.5" fill="#831843">• Medine\'de Mescid-i Nebevî\'nin bitişiğinde kurulan</text>\n  <text x="38" y="118" font-size="11.5" fill="#831843">İslam\'ın ilk yatılı eğitim ve ilim merkezidir.</text>\n  <text x="38" y="144" font-size="11.5" fill="#831843">• Genç sahabiler burada Kur\'an, hadis, yazı ve</text>\n  <text x="38" y="164" font-size="11.5" fill="#831843">dini ilimleri bizzat Peygamberimizden öğrendi.</text>\n  <text x="38" y="190" font-size="11.5" fill="#831843">• Ebû Hüreyre (ra) Suffe\'de yetişerek en çok</text>\n  <text x="38" y="210" font-size="11.5" fill="#831843">hadis rivayet eden sahabi olmuştur.</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İlimde Öncü Genç Sahabiler</text>\n  <text x="378" y="98" font-size="11.5" fill="#581c87">• Zeyd bin Sâbit (ra): Genç vahiy kâtibi; kısa sürede</text>\n  <text x="378" y="118" font-size="11.5" fill="#581c87">yabancı dil öğrendi, Kur\'an\'ı Mushaf hâline getirdi.</text>\n  <text x="378" y="144" font-size="11.5" fill="#581c87">• Hz. Âişe (ra): Kur\'an, hadis ve fıkıh ilminde</text>\n  <text x="378" y="164" font-size="11.5" fill="#581c87">sahabilerin başvurduğu en büyük kadın âlim oldu.</text>\n  <text x="378" y="190" font-size="11.5" fill="#581c87">• Abdullah bin Abbas ve Abdullah bin Ömer (r.anhüm):</text>\n  <text x="378" y="210" font-size="11.5" fill="#581c87">Genç yaşta tefsir ve hadis ilminde uzmanlaştılar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENÇ SAHABİLERİN CESARETİ, FEDAKÂRLIĞI VE TEBLİĞ GAYRETİ</text>\n  <rect x="25" y="48" width="205" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">Hz. Ali (ra)</text>\n  <text x="127" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• Çocuk/genç yaşta iman etti.</text>\n  <text x="127" y="124" text-anchor="middle" font-size="11.5" fill="#155e75">• Hicret gecesi canını tehlikeye</text>\n  <text x="127" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">atarak Peygamberimizin</text>\n  <text x="127" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">yatağında yattı ve emanetleri</text>\n  <text x="127" y="184" text-anchor="middle" font-size="11.5" fill="#155e75">sahiplerine teslim etti.</text>\n  <text x="127" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Emanet ve Cesaret Timsali</text>\n\n  <rect x="247" y="48" width="205" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#c2410c">Erkam bin Ebi\'l-Erkam</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#9a3412">• Henüz 16-17 yaşlarında bir</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11.5" fill="#9a3412">gençken Safâ Tepesi yanındaki</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11.5" fill="#9a3412">evini (Dârü\'l-Erkam) İslam\'ın</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#9a3412">ilk tebliğ ve eğitim merkezi</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11.5" fill="#9a3412">olarak müminlere açtı.</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#ea580c">Fedakârlık ve Tebliğ Yuvası</text>\n\n  <rect x="470" y="48" width="205" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Mus\'ab ve Ca\'fer (r.anhüm)</text>\n  <text x="572" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• Mus\'ab bin Umeyr Medine\'de</text>\n  <text x="572" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">ilk öğretmen oldu; Uhud\'da</text>\n  <text x="572" y="140" text-anchor="middle" font-size="11.5" fill="#14532d">sancağı taşırken şehit düştü.</text>\n  <text x="572" y="164" text-anchor="middle" font-size="11.5" fill="#14532d">• Ca\'fer bin Ebî Tâlib Habeş</text>\n  <text x="572" y="184" text-anchor="middle" font-size="11.5" fill="#14532d">kralı النجاشي huzurunda İslam\'ı savundu.</text>\n  <text x="572" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Tebliğ ve Şehadet Ruhu</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
